"""对外接口。"""

from tokenizer import tokenize
from vocab import count, top


def keyword_summary(text, k=3):
    """给出出现次数最多的前 k 个词元及其占比。

    返回 total 与 top 两个键。top 是 (词, 次数, 占比) 三元组的列表，
    占比按词元总数计算并保留四位小数。文本不含词元时返回总数零与空列表。
    """
    tokens = tokenize(text)
    if not tokens:
        return {"total": 0, "top": []}
    counts = count(tokens)
    return {"total": len(tokens),
            "top": [(word, n, round(n / len(tokens), 4))
                    for word, n in top(counts, k)]}

from summary import keyword_summary


def test_counts_and_shares():
    result = keyword_summary("the cat and the hat and the bat", k=2)
    assert result["total"] == 8
    assert result["top"] == [("the", 3, 0.375), ("and", 2, 0.25)]


def test_ties_are_broken_by_word_order():
    result = keyword_summary("pear apple pear apple plum", k=2)
    assert result["total"] == 5
    assert result["top"] == [("apple", 2, 0.4), ("pear", 2, 0.4)]


def test_punctuation_and_case_are_ignored():
    result = keyword_summary("Dog! dog? DOG.", k=1)
    assert result["total"] == 3
    assert result["top"] == [("dog", 3, 1.0)]


def test_empty_text():
    assert keyword_summary("", k=3) == {"total": 0, "top": []}

"""词频与排序。"""


def count(tokens):
    """统计每个词元的出现次数。"""
    counts = {}
    for token in tokens:
        counts[token] = counts.get(token, 0) + 1
    return counts


def sort_key(pair):
    """排序键。"""
    word, n = pair
    return (n, word)


def top(counts, k):
    """按次数降序、同次按词形升序取前 k 项。"""
    ranked = sorted(counts.items(), key=sort_key, reverse=True)
    return ranked[:k]

